import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
})
export class LoginComponent {
  form: FormGroup;
  loading = false;
  errorMsg = '';
  showPassword = false;

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private router: Router
  ) {
    this.form = this.fb.group({
      alias: ['', [Validators.required]],
      password: ['', [Validators.required]],
    });

    if (this.authService.isLoggedIn) {
      this.router.navigate(['/dashboard']);
    }
  }

  onSubmit(): void {
    if (this.form.invalid) return;
    this.loading = true;
    this.errorMsg = '';
    const { alias, password } = this.form.value;

    this.authService.login(alias, password).subscribe({
      next: () => {
        this.loading = false;
        this.router.navigate(['/dashboard']);
      },
      error: (err) => {
        this.loading = false;
        this.errorMsg =
          err?.error?.message || 'Credenciales inválidas. Intente nuevamente.';
      },
    });
  }
}
<div class="login-wrapper">
  <div class="login-card">
    <div class="text-center mb-4">
      <div class="mb-3">
        <i class="bi bi-headset" style="font-size: 3rem; color: #1e40af;"></i>
      </div>
      <h1 class="login-title">SysApolo</h1>
      <p class="login-subtitle">Sistema de Trazabilidad de Soporte Contable</p>
    </div>

    <form [formGroup]="form" (ngSubmit)="onSubmit()">
      <div class="mb-3">
        <label class="form-label">
          <i class="bi bi-person me-1"></i>Alias de usuario
        </label>
        <input
          type="text"
          class="form-control"
          formControlName="alias"
          placeholder="Ingrese su alias"
          autocomplete="username"
        />
        <div
          class="text-danger small mt-1"
          *ngIf="form.get('alias')?.touched && form.get('alias')?.invalid"
        >
          El alias es requerido
        </div>
      </div>

      <div class="mb-4">
        <label class="form-label">
          <i class="bi bi-lock me-1"></i>Contraseña
        </label>
        <div class="input-group">
          <input
            [type]="showPassword ? 'text' : 'password'"
            class="form-control"
            formControlName="password"
            placeholder="Ingrese su contraseña"
            autocomplete="current-password"
          />
          <button
            type="button"
            class="btn btn-outline-secondary"
            (click)="showPassword = !showPassword"
          >
            <i class="bi" [class.bi-eye]="!showPassword" [class.bi-eye-slash]="showPassword"></i>
          </button>
        </div>
        <div
          class="text-danger small mt-1"
          *ngIf="form.get('password')?.touched && form.get('password')?.invalid"
        >
          La contraseña es requerida
        </div>
      </div>

      <div class="alert alert-danger py-2" *ngIf="errorMsg">
        <i class="bi bi-exclamation-circle me-1"></i>{{ errorMsg }}
      </div>

      <button
        type="submit"
        class="btn btn-primary w-100"
        [disabled]="loading"
      >
        <span
          *ngIf="loading"
          class="spinner-border spinner-border-sm me-2"
        ></span>
        <i class="bi bi-box-arrow-in-right me-1" *ngIf="!loading"></i>
        {{ loading ? 'Ingresando...' : 'Ingresar' }}
      </button>
    </form>
  </div>
</div>
